


/** A link that opens one order, subscription, or Return in the merchant's Flint-hosted customer account without a sign-in. Its url is a bearer credential, returned only when the link is created. */ export type AccessLink = { /** When the link stops opening the resource without a sign-in. Format: date-time. */ "expires_at": string; /** What the link opens and how long it works. New purposes may be added; treat one you don't recognize as opening its resource. */ "purpose": "order_view" | "subscription_view" | "return_view" | (string & {}); /** The link to send the buyer. It carries an access grant in its fragment, so anyone with it can open the resource until expires_at or until it reaches its open limit. The link follows the customer account's current custom domain when the buyer opens it. Format: uri. */ "url": string; };
